import Fastify from "fastify";
import cors from "@fastify/cors";
import { authPlugin, generateToken } from "./middleware/auth.js";
import prisma from "./lib/prisma.js";
import bcrypt from "bcryptjs";

const app = Fastify({
  logger: process.env.NODE_ENV === "development",
});

await app.register(cors);
await app.register(authPlugin);

// POST /api/users - 회원가입
app.post("/api/users", async (request, reply) => {
  const { username, email, password } = (request.body as any).user;

  if (!username || !email || !password) {
    return reply.code(422).send({
      errors: [{ status: "422", title: "Validation error", detail: "username, email, password are required" }],
    });
  }

  const existing = await prisma.user.findFirst({
    where: { OR: [{ username }, { email }] },
  });

  if (existing) {
    return reply.code(422).send({
      errors: [{ status: "422", title: "Validation error", detail: "Username or email already taken" }],
    });
  }

  const hashedPassword = await bcrypt.hash(password, 10);
  const token = generateToken({ id: "", username, email });

  const user = await prisma.user.create({
    data: { username, email, password: hashedPassword, bio: null, image: null, token },
    select: { id: true, username: true, email: true, bio: true, image: true, token: true },
  });

  return reply.code(201).send({ user });
});

// POST /api/users/login - 로그인
app.post("/api/users/login", async (request, reply) => {
  const { email, password } = (request.body as any).user;

  if (!email || !password) {
    return reply.code(401).send({
      errors: [{ status: "401", title: "Unauthorized", detail: "Email and password are required" }],
    });
  }

  const user = await prisma.user.findUnique({ where: { email } });
  if (!user) {
    return reply.code(401).send({
      errors: [{ status: "401", title: "Unauthorized", detail: "Invalid credentials" }],
    });
  }

  const isValid = await bcrypt.compare(password, user.password);
  if (!isValid) {
    return reply.code(401).send({
      errors: [{ status: "401", title: "Unauthorized", detail: "Invalid credentials" }],
    });
  }

  const token = generateToken({ id: user.id, username: user.username, email: user.email });

  await prisma.user.update({
    where: { id: user.id },
    data: { token },
  });

  return reply.send({
    user: {
      id: user.id,
      username: user.username,
      email: user.email,
      bio: user.bio,
      image: user.image,
      token,
    },
  });
});

// GET /api/user - 현재 사용자 정보 조회
app.get("/api/user", { preHandler: app.authenticate }, async (request, reply) => {
  const userId = (request as any).user?.id;
  if (!userId) {
    return reply.code(401).send({ errors: [{ message: "Unauthorized" }] });
  }

  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: { id: true, username: true, email: true, bio: true, image: true, token: true },
  });

  if (!user) {
    return reply.code(404).send({ errors: [{ message: "User not found" }] });
  }

  const token = generateToken({ id: user.id, username: user.username, email: user.email });

  return reply.send({
    user: {
      id: user.id,
      username: user.username,
      email: user.email,
      bio: user.bio ?? null,
      image: user.image ?? null,
      token,
    },
  });
});

// PUT /api/user - 사용자 정보 수정
app.put("/api/user", { preHandler: app.authenticate }, async (request, reply) => {
  const userId = (request as any).user?.id;
  if (!userId) {
    return reply.code(401).send({ errors: [{ message: "Unauthorized" }] });
  }

  const body = request.body as any;
  const updates: any = {};
  const { username, email, password, bio, image } = body.user ?? {};

  if (username !== undefined) updates.username = username;
  if (email !== undefined) updates.email = email;
  if (password !== undefined) updates.password = await bcrypt.hash(password, 10);
  if (bio !== undefined) updates.bio = bio === "" ? null : bio;
  if (image !== undefined) updates.image = image === "" ? null : image;

  // 이메일 중복 체크
  if (email && email !== (await prisma.user.findUnique({ where: { id: userId } })?.email)) {
    const existingByEmail = await prisma.user.findUnique({ where: { email } });
    if (existingByEmail && existingByEmail.id !== userId) {
      return reply.code(422).send({
        errors: [{ status: "422", title: "Validation error", detail: "Email already taken" }],
      });
    }
  }

  // username 중복 체크
  if (username && username !== (await prisma.user.findUnique({ where: { id: userId } })?.username)) {
    const existingByUsername = await prisma.user.findUnique({ where: { username } });
    if (existingByUsername && existingByUsername.id !== userId) {
      return reply.code(422).send({
        errors: [{ status: "422", title: "Validation error", detail: "Username already taken" }],
      });
    }
  }

  const updated = await prisma.user.update({
    where: { id: userId },
    data: updates,
    select: { id: true, username: true, email: true, bio: true, image: true, token: true },
  });

  const newToken = generateToken({
    id: updated.id,
    username: updated.username,
    email: updated.email,
  });

  return reply.send({
    user: {
      id: updated.id,
      username: updated.username,
      email: updated.email,
      bio: updated.bio ?? null,
      image: updated.image ?? null,
      token: newToken,
    },
  });
});

const port = parseInt(process.env.PORT ?? "8000", 10);
await app.listen({ port, host: "0.0.0.0" });
console.log(`RealWorld API server running on http://localhost:${port}`);

